\label{thm:general-entrywise}
  Fix $n\ge3$, a connected comparison design $\mathcal{D}=(G,\{L_e\}_{e\in E})$ with $G=([n],E)$ and positive integer counts $L_e$, and $\bm\theta^\star\in\mathcal{H}$ with dynamic range $\kappa$.
  Let $C$ and $C_{\mathrm{inf}}$ be sufficiently large absolute constants.
  Suppose that   
  \begin{equation}
    \lambda_{\mathcal{D}}\ge C\kappa^2\log n.
  \label{eq:general-baseline}
  \end{equation}
  Then, with probability at least $1-Cn^{-10}$, both the MLE and Rank Centrality estimators exist uniquely and satisfy
  \begin{equation}
    \max_{a\in\{\mathrm{MLE},\mathrm{RC}\}}
    \left\lVert \widehat{\bm\theta}^{a}-\bm\theta^\star\right\rVert_\infty
    \le
    C_{\mathrm{inf}}\kappa\frac{\log^{3/2}n}{\sqrt{\lambda_{\mathcal{D}}}}.
    \label{eq:general-entrywise}
  \end{equation}

\label{cor:general-topk}
  Under \eqref{eq:general-baseline}, both the MLE and Rank Centrality exactly recover the top-$K$ set with probability at least $1-Cn^{-10}$ whenever
  \begin{equation}
    \lambda_{\mathcal{D}}
    >
    C \kappa^2\log n\cdot \max\left\{1, \frac{\log^2 n}{\Delta_K^2}\right\}.
    \label{eq:general-topk-samples}
  \end{equation}

\label{cor:rp-rc}
Define the dynamic ranges
\[
  \kappa_1:=\exp\!\Big(
    \max_{i,j\in[m]}|\theta_i^\star-\theta_j^\star|
  \Big),\qquad
  \kappa_2:=\exp\!\Big(
    \max_{t\in[N],\,i\in[m]}|\zeta_t^\star-\theta_i^\star|
  \Big).
\]
Suppose $mp\ge2$, $m\le N^{100}$, and
\begin{equation}
  Np\ge C\left(
    \kappa_2^2\log N+\kappa_1^2\kappa_2\log m
  \right).
  \label{eq:rp-rc-baseline}
\end{equation}
Then, with probability at least $1-Cm^{-10}-CN^{-10}$, the RP-RC estimator exists uniquely and satisfies
\begin{equation}
  \left\lVert \widehat{\bm\theta}^{\mathrm{RP\text{-}RC}}-\bm\theta^\star\right\rVert_\infty
  \le C\kappa_1\sqrt{\frac{\kappa_2\log^3m}{Np}}.
  \label{eq:rp-rc-rate}
\end{equation}

\label{def:semirandom}
Fix an initial design $\mathcal{D}_0=(G_0,\{L_{ij}^{(0)}\})$, where $G_0=([n],E_0)$ and $L_{ij}^{(0)}$ is a positive integer for every $\{i,j\}\in E_0$ and zero otherwise.
\begin{enumerate}[label=(\roman*)]
  \item \emph{Initial outcomes.}
  Draw $L_{ij}^{(0)}$ independent BTL comparisons on every edge $\{i,j\}\in E_0$.

  \item \emph{Adversarial augmentation.}
  The adversary observes $\mathcal{D}_0$, the initial outcomes, and possibly $\bm\theta^\star$.
  It then chooses nonnegative integers $M_{ij}$ for all pairs $\{i,j\}$, which may be positive for pairs outside $E_0$.
  Conditional on the initial data and these choices, $M_{ij}$ fresh independent BTL comparisons are drawn on each pair $\{i,j\}$.

  \item \emph{Final observations.}
  Let $\mathcal{D}$ be the final design, with counts $L_{ij}=L_{ij}^{(0)}+M_{ij}$.
  The estimators observe all comparisons together, without knowing which were collected initially.
\end{enumerate}

\label{thm:semirandom}
Under \Cref{def:semirandom}, fix $n\ge3$ and $\bm\theta^\star\in\mathcal{H}$ with dynamic range $\kappa$.
There are sufficiently large universal constants $C,C_{\mathrm{inf}}>0$ such that if
\begin{equation}
  \lambda_{\mathcal{D}_0}\ge C\kappa^2\log n,
  \label{eq:semirandom-baseline}
\end{equation}
then, uniformly over the adversary, with probability at least $1-Cn^{-10}$, the MLE and Rank Centrality estimators exist uniquely and satisfy
\[
  \max_{a\in\{\mathrm{MLE},\mathrm{RC}\}}
  \left\lVert \widehat{\bm\theta}^{a}-\bm\theta^\star\right\rVert_\infty
  \le C_{\mathrm{inf}}\kappa
  \frac{\log^{3/2}n}{\sqrt{\lambda_{\mathcal{D}}}}.
\]

\label{lem:localized-process}
  Fix a connected observation design $\mathcal{D}=(G,\{L_e\}_{e\in E})$, where $G=([n],E)$.
  Let $\{\zeta_e:e\in E\}$ be independent, centered random variables satisfying
  \begin{equation}
    \mathbb{E}\exp(t\zeta_e)\le\exp(\tau^2L_et^2/2),
    \qquad t\in\mathbb{R},
    \label{eq:edge-mgf}
  \end{equation}
  and put $\bm z=\sum_{e\in E}\zeta_e\bm b_e$.
  There is a universal constant $C>0$ such that, with probability at least $1-Cn^{-10}$, simultaneously for every nonempty $S\subsetneq[n]$ with $s=|S|\le n/2$ and every $\bm v\in\mathbb{R}^n$ supported on $S$,
  \begin{equation}
    \left\lvert \bm z^\top\bm v\right\rvert
    \le C\tau\sqrt{s\log n}
    \sqrt{\bm v^\top\bm L_{\mathcal{D}}\bm v}.
    \label{eq:localized-process}
  \end{equation}

\label{lem:sparse-poincare}
  For any fixed connected observation design $\mathcal{D}$, every $\bm v\in\mathbb{R}^n$ supported on a set of size at most $n/2$ satisfies
  \begin{equation}
    \bm v^\top\bm L_{\mathcal{D}}\bm v
    \ge\frac{\lambda_{\mathcal{D}}}{2}\left\lVert \bm v\right\rVert_2^2.
    \label{eq:sparse-poincare}
  \end{equation}

\label{lem:spectral-cut-size}
  For any fixed connected observation design $\mathcal{D}$ and every nonempty $S\subsetneq[n]$,
  \begin{equation}
    \sum_{e\in\partial S}
    L_e \ge \lambda_{\mathcal{D}}\frac{|S|(n-|S|)}{n}.
    \label{eq:spectral-cut-size}
  \end{equation}

\label{lem:general-directed-connectivity}
  For a fixed connected observation design $\mathcal{D}$, if
  \begin{equation}
    \frac{\lambda_{\mathcal{D}}}{1+\kappa}\ge C\log n,
    \label{eq:connectivity-baseline}
  \end{equation}
  then $D_{\mathrm{win}}$ is strongly connected with probability at least $1-Cn^{-10}$.

Fix a nonempty $S\subsetneq[n]$.
  For every comparison across its edge boundary, the probability that the endpoint outside $S$ defeats the endpoint in $S$ is at least $1/(1+\kappa)$.
  For $D_\mathrm{win}$, such an outcome creates a directed edge from $S$ to $S^c$.
  Independence across edges and repetitions gives
  \[
    \mathbb{P}\{\text{no directed edge of $D_{\mathrm{win}}$ leaves }S\} \le \exp\!
    \left\{-\frac{\sum_{e\in\partial S}
      L_e}{1+\kappa}\right\}.
  \]
  A directed graph on $[n]$ is strongly connected if and only if every nonempty $S\subsetneq[n]$ has a directed edge from $S$ to $S^c$.
  Applying \Cref{lem:spectral-cut-size} to every such $S$ and then using $n-s\ge n/2$ for $s\le n/2$ yields
  \begin{align*}
    \mathbb{P}\{D_{\mathrm{win}}\text{ is not strongly connected}\}
     & \le
    2\sum_{s=1}^{\lfloor n/2\rfloor}
    \binom ns
    \exp\!\left\{-\frac{\lambda_{\mathcal{D}}s(n-s)}{n(1+\kappa)}\right\} \\
     & \le
    2\sum_{s=1}^{\lfloor n/2\rfloor}
    \exp\!\left\{s\log n-\frac{\lambda_{\mathcal{D}}s}{2(1+\kappa)}\right\}
    \le Cn^{-10}.
  \end{align*}
  The last line follows from \eqref{eq:connectivity-baseline}.

\label{lem:mle-existence}
  If $D_{\mathrm{win}}$ is strongly connected, the loss \eqref{eq:mle-loss} is coercive and strictly convex on $\mathcal{H}$.
  Hence the MLE exists uniquely.

\label{lem:mle-score-localization}
  Define the score at the truth by
  \begin{equation}
    \bm g_{\mathrm{MLE}}:=\nabla\mathcal{L}(\bm\theta^\star)
    =\sum_{e\in E}
    L_e\cdot \bigl(\sigma(\bm b_e^\top\bm\theta^\star)-\overline Y_e\bigr)\bm b_e.
    \label{eq:mle-score}
  \end{equation}
  Whenever the MLE exists, set
  \[
    \bm\delta:=\widehat{\bm\theta}^{\mathrm{MLE}}-\bm\theta^\star.
  \]
  Then
  \begin{equation}
    \bm 0=\bm g_{\mathrm{MLE}}+\sum_{e\in E}
    L_e\cdot\left\{\sigma\bigl(\bm b_e^\top(\bm\theta^\star+\bm\delta)\bigr) -\sigma(\bm b_e^\top\bm\theta^\star)\right\}\bm b_e.
    \label{eq:mle-score-identity}
  \end{equation}
  Condition on the observation design $\mathcal{D}$.
  Then, with probability at least $1-Cn^{-10}$,
  \begin{equation}
    \left\lvert \bm g_{\mathrm{MLE}}^\top\bm v\right\rvert
    \le C\sqrt{s\log n}
    \sqrt{\bm v^\top\bm L_{\mathcal{D}}\bm v}
    \label{eq:mle-localized-score}
  \end{equation}
  simultaneously for every $\bm v$ supported on a set of size $s\le n/2$.

\label{lem:logistic-increment}
  For every $\kappa\ge1$ and $x,u\in\mathbb{R}$ with $|x|\le\log\kappa$,
  \begin{equation}
    \left\lvert \sigma(x+u)-\sigma(x)\right\rvert
    \ge\frac{1}{2(\mathrm{e}+1)\kappa}\min\{|u|,1\}
    \ge\frac{1}{8\kappa}\min\{|u|,1\}.
    \label{eq:logistic-increment}
  \end{equation}

\label{lem:rc-noise-localization}
  Define
  \begin{equation}
    \bm g_{\mathrm{RC}}:=\sum_{e\in E}\gamma_e\cdot\bm b_e.
    \label{eq:rc-score}
  \end{equation}
  Conditional on the observation design $\mathcal{D}$, with probability at least $1-Cn^{-10}$,
  \begin{equation}
    \left\lvert \bm g_{\mathrm{RC}}^\top\bm v\right\rvert
    \le C\kappa\sqrt{s\log n}
    \sqrt{\bm v^\top\bm L_{\mathcal{D}}\bm v}
    \label{eq:rc-localized-score}
  \end{equation}
  simultaneously for all $\bm v$ supported on a set of size $s\le n/2$.

\label{lem:rc-upper-truncation-energy}
  Assume that \eqref{eq:rc-localized-score} in \Cref{lem:rc-noise-localization} holds.
  Suppose $1\le s=|\{i:r_i>t\}|\le n/2$.
  Then the truncation in \eqref{eq:rc-upper-truncation} satisfies
  \begin{equation}
    \bm z^\top\bm L_{\mathcal{D}}\bm z
    \le C\kappa^2\cdot(t+a)^2s\log n.
    \label{eq:rc-upper-truncation-energy}
  \end{equation}

\label{lem:rc-lower-truncation-energy}
  Assume that \eqref{eq:rc-localized-score} in \Cref{lem:rc-noise-localization} holds.
  Suppose $1\le s=|\{i:r_i<t\}|\le n/2$.
  Then the lower truncation in \eqref{eq:rc-lower-truncation} satisfies
  \begin{equation}
    \bm z^\top\bm L_{\mathcal{D}}\bm z
    \le C\kappa^2t^2s\log n.
    \label{eq:rc-lower-truncation-energy}
  \end{equation}

\label{lem:er-gap}
  If $G_0\sim G(n,p)$ and $np\ge C\log n$, then, with probability at least $1-Cn^{-10}$,
  \begin{equation}
    \lambda_2(\bm L_{G_0})\ge\frac12np.
    \label{eq:er-gap}
  \end{equation}
  Consequently, for any integer $L\ge1$, every observation design $\mathcal{D}$ with at least $L$ comparisons on each edge of $G_0$ satisfies $\lambda_{\mathcal{D}}\ge npL/2$ on this event.

\label{lem:adaptive-split-localization}
  Under \Cref{def:semirandom}, suppose that $G_0$ is connected.
  Let $\bm g_{\mathrm{MLE}}$ and $\bm g_{\mathrm{RC}}$ be the final-design score vectors in \eqref{eq:mle-score} and \eqref{eq:rc-score}.
  Uniformly over the adversary, with probability at least $1-Cn^{-10}$, simultaneously for every vector $\bm v$ supported on a set of size $s\le n/2$,
  \begin{align}
    \left\lvert \bm g_{\mathrm{MLE}}^\top\bm v\right\rvert
     &\le C\sqrt{s\log n}
       \sqrt{\bm v^\top\bm L_{\mathcal{D}}\bm v},
    \label{eq:adaptive-mle-localization} \\
    \left\lvert \bm g_{\mathrm{RC}}^\top\bm v\right\rvert
     &\le C\kappa\sqrt{s\log n}
       \sqrt{\bm v^\top\bm L_{\mathcal{D}}\bm v}.
    \label{eq:adaptive-rc-localization}
  \end{align}
